public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    // Check if the string is null or empty
    if (str == null || str.length() == 0) {
        return lb;
    }

    // Get the number of bytes in the string
    int strLen = str.length();

    // Write the length of the string
    lb.putInt(strLen);

    // Write the bytes of the string
    for (int i = 0; i < strLen; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            lb.putByte((byte) c);
        } else if (c < 0x800) {
            lb.putByte((byte) (0xc0 | (c >> 6)));
            lb.putByte((byte) (0x80 | (c & 0x3f)));
        } else if (c < 0xd800 || c >= 0xe000) {
            lb.putByte((byte) (0xe0 | (c >> 12)));
            lb.putByte((byte) (0x80 | ((c >> 6) & 0x3f)));
            lb.putByte((byte) (0x80 | (c & 0x3f)));
        } else {
            // Surrogate pair
            int codePoint = c;
            i++;
            if (i < strLen) {
                char d = str.charAt(i);
                if (d >= 0xdc00 && d < 0xe000) {
                    codePoint = (((codePoint - 0xd800) << 10) | (d - 0xdc00)) + 0x10000;
                }
            }
            lb.putByte((byte) (0xf0 | (codePoint >> 18)));
            lb.putByte((byte) (0x80 | ((codePoint >> 12) & 0x3f)));
            lb.putByte((byte) (0x80 | ((codePoint >> 6) & 0x3f)));
            lb.putByte((byte) (0x80 | (codePoint & 0x3f)));
        }
    }

    return lb;
}

