public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 0) {
      throw new IllegalArgumentException("desiredCapacity must be non-negative");
    }

    if (desiredCapacity == 0) {
      return 1;
    }

    // Find the first prime number that is >= desiredCapacity
    for (int i = 1; i < desiredCapacity; i++) {
      if (isPrime(i)) {
        return i;
      }
    }

    // If we reach this point, we need to find the next prime number
    // after the largest prime number that is < desiredCapacity
    int prime = 0;
    for (int i = desiredCapacity - 1; i >= 1; i--) {
      if (isPrime(i)) {
        prime = i;
        break;
      }
    }

    // If we still haven't found a prime number, return the largest prime number
    // that is < desiredCapacity
    if (prime == 0) {
      return desiredCapacity - 1;
    }

    // Return the next prime number after the largest prime number that is < desiredCapacity
    return prime + 1;
  }

  private static boolean isPrime(int n) {
    if (n == 2 || n == 3) {
      return true;
    }

    if (n < 2 || n % 2 == 0 || n % 3 == 0) {
      return false;
    }

    for (int i = 5; i * i <= n; i += 6) {
      if (n % i == 0 || n % (i + 2) == 0) {
        return false;
      }
    }

    return true;
  }

